const q = $json.query || {};
const b = $json.body  || {};
const url = q.url || b.url || '';
if (!url) {
  // Return a Discord error rather than failing silently
  return [{ json: { error: true, url: '', message: 'No url parameter provided. Use ?url=JOB_URL' } }];
}
return [{ json: { url, error: false } }];

const url  = $('Extract URL').first().json.url;
const raw  = $json.data || $json.body || $json || '';
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);

const resumeText = "Your Name\nYour City, ST | 555.555.0100 | you@example.com | yourwebsite.example | github.com/your-handle\n\nPROFESSIONAL SUMMARY\n[Two or three sentences: years of experience, domains, the kind of role you want next.]\n\nTECHNICAL SKILLS\nRouting & Switching: [skills]\nSecurity: [skills]\nSystems & Virtualization: [skills]\nMonitoring & Automation: [skills]\n\nPROFESSIONAL EXPERIENCE\n[Title] | [Employer] \u2014 [City, ST] | [Year]\u2013Present\n- [Achievement with a number in it]\n- [Achievement with a number in it]\n\n[Title] | [Employer] \u2014 [City, ST] | [Year]\u2013[Year]\n- [Achievement with a number in it]\n\nEDUCATION & CERTIFICATIONS\n[Degree] | [School]\n[Certification] \u2014 [Year]";

// Strip boilerplate: remove "Similar jobs" section and everything after
let content = text;
const simIdx = content.search(/#{2,3}\s*Similar jobs/i);
if (simIdx > 0) content = content.substring(0, simIdx);

// Remove everything before the first H1 (nav/header junk)
const h1idx = content.search(/\n#\s+/);
if (h1idx > 200) content = content.substring(h1idx);

// Trim
content = content.substring(0, 6000).trim();

const prompt = `You are a professional resume writer and career coach helping a senior network/infrastructure engineer apply for a job.

JOB POSTING URL: ${url}

JOB POSTING CONTENT (scraped markdown):
${content}

CANDIDATE BASE RESUME:
${resumeText}

TASK: Extract the job details and generate a complete tailored application package.
Return ONLY valid JSON — no markdown fences, no extra text:

{
  "job": {
    "title": "job title from the posting",
    "company": "company name (if not shown, use the domain name)",
    "location": "city/state or Remote",
    "salary": "salary range as shown, or empty string",
    "is_remote": true or false,
    "role_type": "one of: SRE, Network Engineer, DevOps, Platform Engineer, Cloud Engineer, Infrastructure Engineer, Other",
    "tags": ["up to 8 key technology and skill tags extracted from the posting"]
  },
  "resume_sections": {
    "summary": "2-3 sentence professional summary written specifically for this role at this company",
    "core_competencies": ["10-12 competency phrases most relevant to this specific job — from the candidate's real skills"],
    "experience": [
      {
        "company": "exact company name",
        "title": "exact title held",
        "dates": "date range",
        "bullets": ["2-4 achievement bullets rewritten to lead with skills this job values most — preserve all specific metrics"]
      }
    ],
    "technical_skills": "Technical skills section with technologies most relevant to this role listed first",
    "education": "Bachelor of Applied Science, Information Security Systems | Your University\\nBachelor of Applied Science, Electronics/Communications Engineering Technology | Your University\\nAssociate of Applied Science, Computer/Electronics Engineering Technology | Your University"
  },
  "cover_letter": "Full 3-4 paragraph cover letter. Paragraph 1: specific hook referencing the company and role. Paragraph 2: 2-3 most relevant experiences with metrics. Paragraph 3: specific value proposition for this role. Paragraph 4: professional close with call to action."
}`;

return [{ json: { url, prompt } }];

const resp   = $input.first().json;
const urlRef = $('Extract URL').first().json.url;

let result = {};
const raw  = resp.content?.[0]?.text || '';

try {
  const cleaned = raw.replace(/```json\s*/g,'').replace(/```\s*/g,'').trim();
  result = JSON.parse(cleaned);
} catch(e) {
  result = {
    job: { title: 'Unknown', company: 'Unknown', location: '', salary: '', is_remote: false, role_type: 'Other', tags: [] },
    resume_sections: null,
    cover_letter: raw || 'Generation failed.'
  };
}

const job = result.job || {};
const s   = result.resume_sections;

function slugify(str, max) {
  return (str || '').replace(/[^\w\s-]/g,'').replace(/\s+/g,' ').trim().substring(0, max || 60);
}

const docDate     = new Date().toISOString().split('T')[0];
const folderName  = slugify(`${job.company} - ${job.title}`, 80);
const resumeTitle = `Resume - ${slugify(job.title,45)} - ${(job.company||'').substring(0,25)} ${docDate}`;
const clTitle     = `Cover Letter - ${slugify(job.title,40)} - ${(job.company||'').substring(0,25)} ${docDate}`;

let resumeText = '';
if (s) {
  const expSection = (s.experience || []).map(exp => {
    const bullets = (exp.bullets || []).map(b => '    \u2022 ' + b).join('\n');
    const roleInfo = [exp.title, exp.dates].filter(Boolean).join('  |  ');
    return `${(exp.company||'').toUpperCase()}\n${roleInfo}\n${bullets}`;
  }).join('\n\n');

  resumeText = [
    'YOUR NAME',
    'Your City, WA  \u2022  555.555.0100  \u2022  you@example.com  \u2022  https://yourwebsite.example',
    '',
    `Tailored for: ${job.title} at ${job.company}`,
    '',
    '------------------------------------------------------------',
    'PROFESSIONAL SUMMARY',
    '------------------------------------------------------------',
    s.summary || '',
    '',
    '------------------------------------------------------------',
    'CORE COMPETENCIES',
    '------------------------------------------------------------',
    (s.core_competencies || []).join('  \u2022  '),
    '',
    '------------------------------------------------------------',
    'PROFESSIONAL EXPERIENCE',
    '------------------------------------------------------------',
    expSection,
    '',
    '------------------------------------------------------------',
    'TECHNICAL SKILLS',
    '------------------------------------------------------------',
    s.technical_skills || '',
    '',
    '------------------------------------------------------------',
    'EDUCATION',
    '------------------------------------------------------------',
    s.education || '',
  ].join('\n');
} else {
  resumeText = 'Resume generation failed. Raw Claude output:\n' + raw.substring(0, 2000);
}

const coverLetterText = [
  `${job.company}`,
  `Re: ${job.title}`,
  `Date: ${new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}`,
  '',
  result.cover_letter || 'Cover letter generation failed.',
  '',
  'Sincerely,',
  'Your Name',
  'you@example.com  |  555.555.0100',
  'https://yourwebsite.example',
].join('\n');

// Pre-build batchUpdate bodies so HTTP nodes don't need complex inline expressions
const resumeBatchBody = JSON.stringify({
  requests: [{ insertText: { location: { index: 1 }, text: resumeText } }]
});
const clBatchBody = JSON.stringify({
  requests: [{ insertText: { location: { index: 1 }, text: coverLetterText } }]
});

return [{ json: {
  job, url: urlRef,
  resume_text: resumeText, cover_letter_text: coverLetterText,
  resume_batch_body: resumeBatchBody, cl_batch_body: clBatchBody,
  folder_name: folderName, resume_title: resumeTitle, cl_title: clTitle,
}}];

const d       = $('Parse Apply Docs').first().json;
const resume  = $('Create Resume Doc').first().json;
const cl      = $('Create Cover Letter Doc').first().json;
const folder  = $('Create App Folder').first().json;
const job     = d.job;

const folderId  = folder.id;
const folderUrl = 'https://drive.google.com/drive/folders/' + folderId;
const resumeUrl = 'https://docs.google.com/document/d/' + resume.documentId + '/edit';
const clUrl     = 'https://docs.google.com/document/d/' + cl.documentId + '/edit';
const today     = new Date().toISOString().split('T')[0];

function para(text) {
  return {object:'block',type:'paragraph',paragraph:{rich_text:[{type:'text',text:{content:(text||'').substring(0,2000)}}]}};
}
function h2(text) {
  return {object:'block',type:'heading_2',heading_2:{rich_text:[{type:'text',text:{content:text}}]}};
}

const children = [
  h2('\uD83D\uDCC1 Application Documents'),
  para('\uD83D\uDCC1 Drive Folder: ' + folderUrl),
  para('\uD83D\uDCDD Resume: ' + resumeUrl),
  para('\u2709\uFE0F Cover Letter: ' + clUrl),
  {object:'block',type:'divider',divider:{}},
  h2('\uD83D\uDD17 Source'),
  para('Manually added via apply-url webhook'),
  para('URL: ' + (d.url || '')),
];

const body = {
  parent: { database_id: "YOUR_NOTION_DB_MAIN" },
  properties: {
    "Job Title":   { title:      [{ text: { content: (job.title   ||'Unknown').substring(0,200) } }] },
    "Company":     { rich_text:  [{ text: { content: (job.company ||'Unknown').substring(0,200) } }] },
    "Source":      { select:     { name: 'Manual' } },
    "Apply URL":   { url: d.url || null },
    "Location":    { rich_text:  [{ text: { content: (job.location||'').substring(0,200) } }] },
    // Score and Priority deliberately omitted: an empty Score is what
    // makes this row eligible for the on-demand scorer (Status ->
    // "Score Me"), which then sets both from the real fit result.
    "Role Type":   { select:     { name: job.role_type || 'Other' } },
    "Tags":        { multi_select: (job.tags||[]).map(t => ({name: String(t).substring(0,100)})) },
    "Status":      { select:     { name: 'Docs Ready' } },
    "Drive Folder":{ url: folderUrl },
    "Date Found":  { date:       { start: today } },
  },
  children,
};

const salaryLine = job.salary ? '\n\uD83D\uDCB0 ' + job.salary : '';
const locLine    = job.location ? '\n\uD83D\uDCCD ' + job.location + (job.is_remote ? ' (Remote)' : '') : '';

const discordMsg = [
  '\uD83D\uDCC4 **Application docs ready!** (Manual add)',
  '**' + (job.title||'?') + '** @ ' + (job.company||'?'),
  job.salary   ? '\uD83D\uDCB0 ' + job.salary   : '',
  job.location ? '\uD83D\uDCCD ' + job.location + (job.is_remote ? ' (Remote)' : '') : '',
  '',
  '\uD83D\uDCC1 [Application Folder](' + folderUrl + ')',
  '\uD83D\uDCDD [Tailored Resume](' + resumeUrl + ')',
  '\u2709\uFE0F [Cover Letter](' + clUrl + ')',
  '',
  'Apply: ' + (d.url || ''),
].filter(Boolean).join('\n');

return [{ json: { notion_body: JSON.stringify(body), discord_msg: discordMsg } }];
